/* @lc app=leetcode id=3613 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = generateSequence(x) { if (p[it] == it) null else p[it] }.toList().let { path -> path.last().also { r -> path.forEach { p[it] = r } } } fun minCost(n: Int, edges: Array<IntArray>, k: Int): Int = IntArray(n) { it }.let { p -> if (k >= n) 0 else edges.sortedBy { it[2] }.fold(0 to 0) { (u, w), e -> if (u < n - k && find(p, e[0]) != find(p, e[1])) p.set(find(p, e[0]), find(p, e[1])).let { u + 1 to e[2] } else u to w }.second } }